// Sakura Sentinels — campaign, Bounty arenas, Total Assault and Tactical Challenge
// (owner: world). See CONTRACTS.md §4, docs/CAMPAIGN.md and docs/BESTIARY.md.
//
// Design rules this file follows:
// * Every chapter teaches one mechanic family; each stage introduces at most a few enemies.
// * Free recruits are granted on the first clear of the stage right BEFORE the mechanic they
//   counter (Yuki before hasty goblins, Kage before veils, Shiro before armor...).
// * Waves are generated by the sim from `waveGen` (deterministic per stage + wave). Pools
//   ramp new enemies in with `from`; minibosses and bosses are scripted in `fixed`.
// * Difficulty ramps by enemy HP, wave budget and wave count (12 → 30), and by the mechanics
//   themselves. Every campaign stage carries an explicit, probe-calibrated `hpScale`: the
//   balance probe (tools/balance/measure.mjs) sets it so each stage lands on the headroom curve
//   in docs/BALANCE.md (Normal: 1-1 ×2.0 … x-5 ×1.4). It is NOT monotone inside a chapter (map
//   length, enemy mix and fresh recruits make stages differ by up to ×2); difficulty is what
//   ramps. Coins follow the smooth index curve below, so retuning a stage's HP never changes
//   its income. Re-probe after map path changes (path length moves headroom).
// * Drops: every campaign stage drops coins, books and two material families (all seven
//   families are farmable in the campaign); rarity improves by chapter and difficulty.
//   Bounty arenas farm one resource line each with better rarity per tier; Total Assault
//   bosses drop crowns, mythic/legendary materials, boss tokens and gear boxes.
//
// Item ids follow CONTRACTS §5. Gear boxes use `gearbox_<rarity>` (category 'gearbox').

import { ENEMY_MAP } from './enemies.js';

// ---------------------------------------------------------------------------
// Builders (internal)
// ---------------------------------------------------------------------------

/** Wave pool entry. */
const P = (enemy, weight, from = 1, to = undefined) => (to == null ? { enemy, weight, from } : { enemy, weight, from, to });
/** Scripted wave addition. */
const F = (wave, enemy, count = 1, spacing = undefined, delay = undefined) => {
  const f = { wave, enemy, count };
  if (spacing != null) f.spacing = spacing;
  if (delay != null) f.delay = delay;
  return f;
};
/** Drop table entry. */
const D = (item, chance, min = 1, max = min, difficulty = undefined) => (difficulty
  ? { item, chance, min, max, difficulty }
  : { item, chance, min, max });
const mat = (family, rarity) => `mat_${family}_${rarity}`;
const book = (rarity) => `book_${rarity}`;
const box = (rarity) => `gearbox_${rarity}`;

const round = (v, step = 1) => Math.round(v / step) * step;

// Smooth campaign index curve 0..39 → 1.0 … 6.5. It is the COIN curve (and the fallback hpScale
// of a stage without an explicit one); real enemy HP is the per-stage calibrated `hpScale`.
const HP_TOP = 6.5;
const hpScaleAt = (i) => Math.round(HP_TOP ** (i / 39) * 100) / 100;
// Economy scale (kill bounties + wave-clear bonus, applied by the sim): curve^0.45 with a 1.3
// floor, so chapters 1–2 pay enough for a first tier 4 by ~70 % of the waves and late chapters
// (cheaper prices since the "frisk1636" playtest) are not flooded: 1.3 at 1-1 … 2.32 at 8-5.
const CASH_FLOOR = 1.3;
const cashScaleFor = (curve) => Math.round(curve ** 0.45 * 100) / 100;
const campaignCashScale = (i) => Math.max(CASH_FLOOR, cashScaleFor(hpScaleAt(i)));
// Start cash 650 at 1-1 rising to 900 at 8-5.
const startCashAt = (i) => (i === 0 ? 650 : round(700 + (200 * (i - 1)) / 38, 10));

/**
 * Campaign drop table. Rarity of materials/books improves by chapter; harder difficulties
 * add better rolls. `fam` = [primary, secondary] material families.
 */
function campaignDrops(chapter, fam, { dice = 0, crown = null } = {}) {
  const [a, b] = fam;
  const c = chapter;
  const coins = [600 + 150 * c, 1000 + 250 * c];
  const drops = [D('coins', 1, coins[0], coins[1])];
  // Books
  if (c <= 4) drops.push(D(book('common'), 0.85, 1, 3));
  drops.push(D(book('rare'), Math.min(0.9, 0.2 + 0.1 * c), 1, c >= 5 ? 2 : 1));
  if (c >= 3) drops.push(D(book('superRare'), 0.08 + 0.03 * c, 1, 1, c >= 6 ? 'normal' : 'hard'));
  if (c >= 6) drops.push(D(book('mythic'), 0.04 + 0.01 * (c - 6), 1, 1, 'hard'));
  // Materials: primary family
  if (c <= 3) drops.push(D(mat(a, 'common'), 0.9, 2, 4));
  drops.push(D(mat(a, 'rare'), c <= 2 ? 0.25 : c <= 5 ? 0.6 : 0.85, 1, c >= 4 ? 3 : 2, c <= 1 ? 'normal' : undefined));
  if (c >= 3) drops.push(D(mat(a, 'superRare'), c <= 5 ? 0.12 : 0.3, 1, c >= 7 ? 2 : 1, c <= 4 ? 'hard' : undefined));
  if (c >= 6) drops.push(D(mat(a, 'mythic'), 0.03 + 0.02 * (c - 6), 1, 1, 'hard'));
  if (c >= 8) drops.push(D(mat(a, 'legendary'), 0.02, 1, 1, 'nightmare'));
  // Materials: secondary family (one step behind)
  drops.push(D(mat(b, 'common'), c <= 4 ? 0.6 : 0.4, 1, 3));
  if (c >= 2) drops.push(D(mat(b, 'rare'), c <= 4 ? 0.2 : 0.45, 1, 2));
  if (c >= 5) drops.push(D(mat(b, 'superRare'), 0.1, 1, 1, 'hard'));
  // Occasional dice and gear
  if (dice > 0) drops.push(D('dice_reroll', dice, 1, 1));
  if (c >= 4) drops.push(D(box(c >= 7 ? 'superRare' : 'rare'), 0.06 + 0.01 * c, 1, 1, 'hard'));
  // Miniboss / boss crowns
  if (crown) {
    drops.push(D(crown.id, crown.chance, 1, 1));
    drops.push(D(crown.id, crown.chance * 0.8, 1, 1, 'hard'));
    drops.push(D('token_boss', 1, crown.tokens, crown.tokens + 2));
  }
  return drops;
}

/**
 * First-clear books per chapter: enough that the free squad reaches EXPECTED_LEVEL
 * (tools/balance/f2p.mjs) without farming in chapters 1–3 (docs/BALANCE.md §7).
 */
function firstClearBooks(chapter) {
  if (chapter <= 2) return { id: book('rare'), count: 4 };
  if (chapter <= 4) return { id: book('superRare'), count: 2 };
  if (chapter <= 6) return { id: book('superRare'), count: 3 };
  return { id: book('superRare'), count: 4 };
}

/** First-clear rewards (on top of the difficulty gem bonus). */
function campaignFirstClear(chapter, finale) {
  const out = [{ id: 'coins', count: 1500 + 500 * chapter }, firstClearBooks(chapter)];
  if (finale) {
    out.push({ id: 'gems', count: 100 + 20 * chapter }, { id: 'ticket_recruit', count: 1 });
  }
  return out;
}

/** Per-wave budget growth that takes the start budget to `final` on the last wave. */
const growthFor = (start, final, waves) => Math.round((final / start) ** (1 / Math.max(1, waves - 1)) * 10000) / 10000;

const CAMPAIGN_ORDER = [];

/**
 * Builds a campaign StageDef. Ids are 'c-n'; requires = previous campaign stage.
 * @param {object} o stage parameters
 * @returns {object} StageDef
 */
function campaign(o) {
  const index = CAMPAIGN_ORDER.length;
  const requires = index === 0 ? null : CAMPAIGN_ORDER[index - 1];
  CAMPAIGN_ORDER.push(o.id);
  const chapter = Number(o.id.split('-')[0]);
  const finale = o.id.endsWith('-5');
  return {
    id: o.id,
    kind: 'campaign',
    chapter,
    name: o.name,
    mapId: o.mapId,
    desc: o.desc,
    waves: o.waves,
    waveGen: {
      pool: o.pool,
      budget: { start: o.budget[0], growth: growthFor(o.budget[0], o.budget[1], o.waves) },
      spacing: o.spacing ?? 0.8,
      groups: o.groups ?? 3,
      fixed: o.fixed || [],
    },
    hpScale: o.hpScale ?? hpScaleAt(index),
    cashScale: o.cashScale ?? campaignCashScale(index),
    startCash: o.startCash ?? startCashAt(index),
    lives: 100,
    introduces: o.introduces || [],
    recommended: o.recommended || [],
    unlocks: o.unlocks ? { units: o.unlocks } : {},
    requires,
    drops: campaignDrops(chapter, o.fam, { dice: o.dice ?? (chapter >= 3 ? 0.04 : 0), crown: o.crown || null }),
    firstClear: campaignFirstClear(chapter, finale),
    scenery: o.scenery,
    tier: o.tier,
  };
}

