export const STAGES = [...CAMPAIGN, ...BOUNTY, ...BOSSES, CHALLENGE];

export const STAGE_MAP = Object.fromEntries(STAGES.map((s) => [s.id, s]));

/**
 * Look up a stage definition.
 * @param {string} id stage id, e.g. '1-1', 'res-books-2', 'boss-lych', 'challenge'
 * @returns {object} StageDef
 * @throws {Error} when the id is unknown
 */
export function getStage(id) {
  const s = STAGE_MAP[id];
  if (!s) throw new Error(`Unknown stage: ${id}`);
  return s;
}

/** @returns {object[]} the 40 campaign stages in play order */
export function campaignStages() {
  return CAMPAIGN.slice();
}

/**
 * @param {'campaign'|'resource'|'boss'|'challenge'} kind
 * @returns {object[]} stages of that kind in display order
 */
export function stagesOfKind(kind) {
  return STAGES.filter((s) => s.kind === kind);
}

/**
 * Bounty arenas grouped for the Bounty screen.
 * @returns {{ id: string, name: string, desc: string, mapId: string, stages: string[] }[]}
 */
export function bountyArenas() {
  return BOUNTY_DEFS.map((d) => ({ id: d.id, name: d.name, desc: d.desc, mapId: d.mapId, stages: [1, 2, 3].map((t) => `${d.id}-${t}`) }));
}

/**
 * Every enemy id that can appear in a stage, including split/brood/summon/decoy children.
 * @param {object|string} stageOrId StageDef or id
 * @param {(id: string) => object|undefined} [lookupEnemy] enemy lookup (defaults to the real bestiary)
 * @returns {string[]}
 */
export function stageEnemies(stageOrId, lookupEnemy = (id) => ENEMY_MAP[id]) {
  const stage = typeof stageOrId === 'string' ? getStage(stageOrId) : stageOrId;
  const out = new Set();
  const visit = (id, depth) => {
    if (out.has(id) || depth > 4) return;
    out.add(id);
    const def = lookupEnemy(id);
    if (!def) return;
    const sets = [def.traits || {}, ...(def.phases || []).map((ph) => ph.set?.traits || {})];
    for (const t of sets) for (const k of ['brood', 'splitter', 'summoner', 'decoy']) if (t[k]?.spawn) visit(t[k].spawn, depth + 1);
  };
  for (const p of stage.waveGen.pool) visit(p.enemy, 0);
  for (const f of stage.waveGen.fixed) visit(f.enemy, 0);
  return [...out];
}

/** Campaign stage ids in play order. */
export const CAMPAIGN_IDS = CAMPAIGN_ORDER.slice();
